US-003 | Each overlay destination is a regular file byte-equal to overlay(base) under an INDEPENDENT re-derivation of the substitution, and every `find` anchor matches exactly once against the PRISTINE base. This oracle deliberately re-implements the substitution instead of calling the generator, so a generator that is merely self-consistent cannot green it; it simultaneously covers the exactly-one-match criterion and the hand-edited-generated-file criterion. Species: CHANGE-DETECTION. Oracle:
bun -e '
const fs = require("node:fs");
const DIR = "scripts/overlays";
let rc = 0;
const files = fs.readdirSync(DIR).filter(f => f.endsWith(".json")).sort();
if (files.length === 0) { console.error("overlay manifest set is empty"); process.exit(1); }
for (const f of files) {
  const o = JSON.parse(fs.readFileSync(`${DIR}/${f}`, "utf8"));
  const base = fs.readFileSync(o.base, "utf8");
  let out = base;
  for (const { find, replace } of o.pairs) {
    const n = base.split(find).length - 1;
    if (n !== 1) { console.error(`${f}: anchor matches ${n}x against pristine base (must be exactly 1): ${JSON.stringify(find.slice(0,60))}`); rc = 1; continue; }
    out = out.replace(find, replace);
  }
  if (fs.lstatSync(o.dest).isSymbolicLink()) { console.error(`${f}: ${o.dest} must be a regular file, not a symlink`); rc = 1; }
  if (fs.readFileSync(o.dest, "utf8") !== out) { console.error(`${f}: ${o.dest} != overlay(${o.base}) - hand-edited or stale`); rc = 1; }
}
process.exit(rc);
'
